1	package chainledger
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// sharedCDList builds the headline alias graph without going through Register:
9	// A and B are roots, C and D both depend on A and B. Every record is
10	// independent, but A.Children and B.Children share one backing array
11	// ([C D]), just as two slices produced by reslicing the same storage do.
12	func sharedCDList() (map[string]*Lineage, *Lineage, *Lineage, *Lineage, *Lineage) {
13		shared := []string{"C", "D"}
14		a := &Lineage{Dataset: "A", Children: shared}
15		b := &Lineage{Dataset: "B", Children: shared}
16		c := &Lineage{Dataset: "C", Parents: append([]string(nil), "A", "B")}
17		d := &Lineage{Dataset: "D", Parents: append([]string(nil), "A", "B")}
18		graph := map[string]*Lineage{"A": a, "B": b, "C": c, "D": d}
19		return graph, a, b, c, d
20	}
21	
22	// TestRegisterSharedChildrenStorageRepoint is the headline fix: replacing C's
23	// upstreams with only B must leave A.Children == [D], B.Children == [C D],
24	// D.Parents == [A B], and C's own downstream records untouched — even though
25	// A and B's downstream lists share one backing array.
26	func TestRegisterSharedChildrenStorageRepoint(t *testing.T) {
27		graph, heldA, heldB, heldC, heldD := sharedCDList()
28	
29		if err := Register(graph, Dataset{Name: "C"}, []string{"B"}); err != nil {
30			t.Fatalf("Register(C, [B]) unexpected error: %v", err)
31		}
32		assertLineageConsistent(t, graph)
33	
34		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
35			t.Errorf("C.Parents = %v, want [B]", got)
36		}
37		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"D"}) {
38			t.Errorf("A.Children = %v, want [D]", got)
39		}
40		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
41			t.Errorf("B.Children = %v, want [C D] (must not lose C or duplicate D)", got)
42		}
43		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
44			t.Errorf("D.Parents = %v, want [A B] (unrelated record must stay unchanged)", got)
45		}
46		if got := graph["C"].Children; len(got) != 0 {
47			t.Errorf("C.Children = %v, want empty", got)
48		}
49	
50		// Records the caller already held must read the same correct relations.
51		if got := heldA.Children; !reflect.DeepEqual(got, []string{"D"}) {
52			t.Errorf("held A record Children = %v, want [D]", got)
53		}
54		if got := heldB.Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
55			t.Errorf("held B record Children = %v, want [C D]", got)
56		}
57		if got := heldC.Parents; !reflect.DeepEqual(got, []string{"B"}) {
58			t.Errorf("held C record Parents = %v, want [B]", got)
59		}
60		if got := heldD.Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
61			t.Errorf("held D record Parents = %v, want [A B]", got)
62		}
63	}
64	
65	// TestRegisterSharedChildrenStorageKeepEdge checks that when the changed
66	// dataset keeps the edge into a list sharing storage with another node's list,
67	// neither list is mutated by in-place removal.
68	func TestRegisterSharedChildrenStorageKeepEdge(t *testing.T) {
69		graph, _, heldB, _, heldD := sharedCDList()
70	
71		// Replace C's parents with [A] (A kept, B dropped).
72		if err := Register(graph, Dataset{Name: "C"}, []string{"A"}); err != nil {
73			t.Fatalf("Register(C, [A]) unexpected error: %v", err)
74		}
75		assertLineageConsistent(t, graph)
76		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
77			t.Errorf("A.Children = %v, want [C D]", got)
78		}
79		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"D"}) {
80			t.Errorf("B.Children = %v, want [D]", got)
81		}
82		if got := heldB.Children; !reflect.DeepEqual(got, []string{"D"}) {
83			t.Errorf("held B record Children = %v, want [D]", got)
84		}
85		if got := heldD.Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
86			t.Errorf("held D record Parents = %v, want [A B]", got)
87		}
88	}
89	
90	// TestRegisterOverlappingChildrenSlices covers the partial-overlap variant:
91	// two child lists share only an interval of their backing storage (different
92	// lengths and offsets into the same array).
93	func TestRegisterOverlappingChildrenSlices(t *testing.T) {
94		// Backing array [C D E Z]: A's list is the [C D E] window and B's list
95		// is the [D E] window, so the two lists overlap on [D E].
96		backing := []string{"C", "D", "E", "Z"}
97		a := &Lineage{Dataset: "A", Children: backing[:3]}  // [C D E]
98		b := &Lineage{Dataset: "B", Children: backing[1:3]} // [D E]
99		c := &Lineage{Dataset: "C", Parents: []string{"A"}}
100		d := &Lineage{Dataset: "D", Parents: []string{"A", "B"}}
101		e := &Lineage{Dataset: "E", Parents: []string{"A", "B"}}
102		graph := map[string]*Lineage{"A": a, "B": b, "C": c, "D": d, "E": e}
103	
104		// C moves from A to B. A's list loses C, B's list gains C; the shared
105		// [D E] window must survive in both with no corruption.
106		if err := Register(graph, Dataset{Name: "C"}, []string{"B"}); err != nil {
107			t.Fatalf("Register(C, [B]) unexpected error: %v", err)
108		}
109		assertLineageConsistent(t, graph)
110		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"D", "E"}) {
111			t.Errorf("A.Children = %v, want [D E]", got)
112		}
113		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D", "E"}) {
114			t.Errorf("B.Children = %v, want [C D E]", got)
115		}
116		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
117			t.Errorf("D.Parents = %v, want [A B]", got)
118		}
119		if got := graph["E"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
120			t.Errorf("E.Parents = %v, want [A B]", got)
121		}
122	}
123	
124	// TestRegisterAddIntoListWithSpareCapacity covers adding an edge into a child
125	// list that carries spare capacity: a second record's list may share that
126	// tail storage, so appending into the spare capacity must never overwrite a
127	// name the other record still uses.
128	func TestRegisterAddIntoListWithSpareCapacity(t *testing.T) {
129		// B.Children = [D] with two slots of spare capacity. A.Children aliases
130		// the tail window of the SAME backing array ([Y Z]), so the graph is
131		// consistent but an in-place append into B would overwrite A's names.
132		backing := make([]string, 3, 3)
133		backing[0] = "D"
134		backing[1] = "Y"
135		backing[2] = "Z"
136		b := &Lineage{Dataset: "B", Children: backing[:1]}  // [D], sees the spare capacity
137		a := &Lineage{Dataset: "A", Children: backing[1:3]} // [Y Z], same array
138		c := &Lineage{Dataset: "C", Parents: nil}           // root so far
139		d := &Lineage{Dataset: "D", Parents: []string{"B"}}
140		y := &Lineage{Dataset: "Y", Parents: []string{"A"}}
141		z := &Lineage{Dataset: "Z", Parents: []string{"A"}}
142		graph := map[string]*Lineage{"A": a, "B": b, "C": c, "D": d, "Y": y, "Z": z}
143	
144		// C gains B as its only upstream: B.Children must become [C D] without
145		// touching the [Y Z] names living in B's spare capacity (which A's list
146		// is modeled as owning independently).
147		if err := Register(graph, Dataset{Name: "C"}, []string{"B"}); err != nil {
148			t.Fatalf("Register(C, [B]) unexpected error: %v", err)
149		}
150		assertLineageConsistent(t, graph)
151		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
152			t.Errorf("B.Children = %v, want [C D]", got)
153		}
154		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"Y", "Z"}) {
155			t.Errorf("A.Children = %v, want [Y Z] (spare-capacity write leaked)", got)
156		}
157	}
158	
159	// TestRegisterMixedChangeWithSharedStorage exercises one replacement that
160	// removes an old upstream, keeps an existing one, and adds a new one at the
161	// same time, with child lists sharing storage.
162	func TestRegisterMixedChangeWithSharedStorage(t *testing.T) {
163		// A and X currently list [C D] sharing storage; B lists [D]. C depends
164		// on A and X. Replace C's parents with [X B]: A loses C, X keeps C, B
165		// gains C. D keeps depending on A, X, and B... set D on A, X, B.
166		shared := []string{"C", "D"}
167		a := &Lineage{Dataset: "A", Children: shared}
168		x := &Lineage{Dataset: "X", Children: shared}
169		b := &Lineage{Dataset: "B", Children: []string{"D"}}
170		c := &Lineage{Dataset: "C", Parents: []string{"A", "X"}}
171		d := &Lineage{Dataset: "D", Parents: []string{"A", "B", "X"}}
172		graph := map[string]*Lineage{"A": a, "B": b, "C": c, "D": d, "X": x}
173	
174		if err := Register(graph, Dataset{Name: "C"}, []string{"B", "X", "X"}); err != nil {
175			t.Fatalf("Register(C, [B X X]) unexpected error: %v", err)
176		}
177		assertLineageConsistent(t, graph)
178		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B", "X"}) {
179			t.Errorf("C.Parents = %v, want [B X]", got)
180		}
181		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"D"}) {
182			t.Errorf("A.Children = %v, want [D]", got)
183		}
184		if got := graph["X"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
185			t.Errorf("X.Children = %v, want [C D]", got)
186		}
187		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
188			t.Errorf("B.Children = %v, want [C D]", got)
189		}
190		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"A", "B", "X"}) {
191			t.Errorf("D.Parents = %v, want [A B X] (unrelated record changed)", got)
192		}
193	}
194	
195	// TestRegisterNewDatasetIntoSharedChildLists covers registration of a brand
196	// new dataset when both upstreams' child lists share backing storage: A and B
197	// both currently list only D, with spare capacity behind the shared window.
198	// Both must independently end up listing [C D]; the second insertion must not
199	// see the first one's write.
200	func TestRegisterNewDatasetIntoSharedChildLists(t *testing.T) {
201		backing := make([]string, 1, 3)
202		backing[0] = "D"
203		shared := backing[:1]
204		a := &Lineage{Dataset: "A", Children: shared}
205		b := &Lineage{Dataset: "B", Children: shared}
206		d := &Lineage{Dataset: "D", Parents: []string{"A", "B"}}
207		graph := map[string]*Lineage{"A": a, "B": b, "D": d}
208	
209		if err := Register(graph, Dataset{Name: "C"}, []string{"A", "B"}); err != nil {
210			t.Fatalf("Register(C, [A B]) unexpected error: %v", err)
211		}
212		assertLineageConsistent(t, graph)
213		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
214			t.Errorf("A.Children = %v, want [C D]", got)
215		}
216		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
217			t.Errorf("B.Children = %v, want [C D]", got)
218		}
219		if got := graph["D"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
220			t.Errorf("D.Parents = %v, want [A B]", got)
221		}
222		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
223			t.Errorf("C.Parents = %v, want [A B]", got)
224		}
225		// The rebuilt lists are independent storage now.
226		graph["A"].Children = append(graph["A"].Children, "leak")
227		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
228			t.Errorf("B.Children = %v, want [C D] after mutating A's list", got)
229		}
230	}
231	
232	// TestRegisterPreservesOwnDownstreamSharedStorage verifies that the changed
233	// dataset keeps its own downstream even when its child list shares storage
234	// with an unrelated record's list, and that other record is left intact.
235	func TestRegisterPreservesOwnDownstreamSharedStorage(t *testing.T) {
236		// C and X both list child E through the same backing array window.
237		backing := make([]string, 1, 3)
238		backing[0] = "E"
239		c := &Lineage{Dataset: "C", Parents: []string{"A", "B"}, Children: backing[:1]}
240		x := &Lineage{Dataset: "X", Children: backing[:1]}
241		e := &Lineage{Dataset: "E", Parents: []string{"C", "X"}}
242		a := &Lineage{Dataset: "A", Children: []string{"C"}}
243		b := &Lineage{Dataset: "B", Children: []string{"C"}}
244		graph := map[string]*Lineage{"A": a, "B": b, "C": c, "E": e, "X": x}
245	
246		if err := Register(graph, Dataset{Name: "C"}, []string{"B"}); err != nil {
247			t.Fatalf("Register(C, [B]) unexpected error: %v", err)
248		}
249		assertLineageConsistent(t, graph)
250		if got := graph["A"].Children; len(got) != 0 {
251			t.Errorf("A.Children = %v, want empty", got)
252		}
253		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
254			t.Errorf("B.Children = %v, want [C]", got)
255		}
256		if got := graph["C"].Children; !reflect.DeepEqual(got, []string{"E"}) {
257			t.Errorf("C.Children = %v, want [E] (own downstream preserved)", got)
258		}
259		if got := graph["X"].Children; !reflect.DeepEqual(got, []string{"E"}) {
260			t.Errorf("X.Children = %v, want [E] (unrelated list untouched)", got)
261		}
262		if got := graph["E"].Parents; !reflect.DeepEqual(got, []string{"C", "X"}) {
263			t.Errorf("E.Parents = %v, want [C X]", got)
264		}
265	}
266	
267	// TestRegisterRejectionWithSharedStorageAtomic verifies that a rejected
268	// registration leaves every record exactly as it was, including lists that
269	// share storage.
270	func TestRegisterRejectionWithSharedStorageAtomic(t *testing.T) {
271		t.Run("missing upstream", func(t *testing.T) {
272			graph, heldA, heldB, heldC, heldD := sharedCDList()
273			err := Register(graph, Dataset{Name: "C"}, []string{"B", "ghost"})
274			if err == nil {
275				t.Fatal("expected error for missing upstream")
276			}
277			if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
278				t.Errorf("C.Parents = %v, want [A B]", got)
279			}
280			if got := heldC.Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
281				t.Errorf("held C record Parents = %v, want [A B]", got)
282			}
283			if got := heldA.Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
284				t.Errorf("A.Children = %v, want [C D]", got)
285			}
286			if got := heldB.Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
287				t.Errorf("B.Children = %v, want [C D]", got)
288			}
289			if got := heldD.Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
290				t.Errorf("D.Parents = %v, want [A B]", got)
291			}
292		})
293	
294		t.Run("indirect cycle", func(t *testing.T) {
295			// A <- C, and C <- D; making A depend on C already handled elsewhere,
296			// here: C depends on A,B and has child D depending on C. Registering A
297			// with upstream D forms A -> D -> C -> A.
298			graph, heldA, heldB, heldC, _ := sharedCDList()
299			mustRegister(t, graph, "E", "C") // E depends on C
300			err := Register(graph, Dataset{Name: "A"}, []string{"E"})
301			if err == nil {
302				t.Fatal("expected cycle error")
303			}
304			if got := heldA.Parents; len(got) != 0 {
305				t.Errorf("A.Parents = %v, want still root", got)
306			}
307			if got := heldA.Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
308				t.Errorf("A.Children = %v, want [C D]", got)
309			}
310			if got := heldB.Children; !reflect.DeepEqual(got, []string{"C", "D"}) {
311				t.Errorf("B.Children = %v, want [C D]", got)
312			}
313			if got := heldC.Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
314				t.Errorf("C.Parents = %v, want [A B]", got)
315			}
316		})
317	}
