1	package chainledger
2	
3	import (
4		"errors"
5		"fmt"
6		"reflect"
7		"sort"
8		"testing"
9	)
10	
11	func mustRegister(t *testing.T, graph map[string]*Lineage, name string, parents ...string) {
12		t.Helper()
13		if err := Register(graph, Dataset{Name: name}, parents); err != nil {
14			t.Fatalf("Register(%q, %v) unexpected error: %v", name, parents, err)
15		}
16	}
17	
18	func TestRegisterBuildsChain(t *testing.T) {
19		graph := map[string]*Lineage{}
20		mustRegister(t, graph, "A")
