196			if got := graph["A"].Parents; len(got) != 0 {
197				t.Errorf("A.Parents = %v, want empty", got)
198			}
199			if got := graph["C"].Children; len(got) != 0 {
200				t.Errorf("C.Children = %v, want empty", got)
201			}
