210				t.Fatalf("idempotent B->A rejected: %v", err)
211			}
212		})
213	
214		t.Run("removed edge must not reject a legal swap", func(t *testing.T) {
215			// P<-A<-X. Replace X's parents with P outright. In the OLD graph X
216			// already reaches P (via A), so a naive check rejects it; after the
217			// replacement the path X->A is gone and X->P is a plain edge.
218			graph := map[string]*Lineage{}
219			mustRegister(t, graph, "P")
220			mustRegister(t, graph, "A", "P")
221			mustRegister(t, graph, "X", "A")
222			if err := Register(graph, Dataset{Name: "X"}, []string{"P"}); err != nil {
223				t.Fatalf("legal replacement judged against removed edge: %v", err)
224			}
225			if got := graph["X"].Parents; !reflect.DeepEqual(got, []string{"P"}) {
226				t.Fatalf("X.Parents = %v, want [P]", got)
227			}
228			if got := graph["A"].Children; len(got) != 0 {
229				t.Fatalf("A.Children = %v, want empty (X detached)", got)
230			}
231			if got := graph["P"].Children; !reflect.DeepEqual(got, []string{"A", "X"}) {
232				t.Fatalf("P.Children = %v, want [A X]", got)
233			}
234		})
235	
236		t.Run("single registration replacing edges judged by final shape", func(t *testing.T) {
237			// A<-B. Re-register B depending on a fresh child-less dataset is
238			// fine; the key case: B stays on A but also gains a parent that
239			// only reaches B via an edge removed in THIS registration.
240			// A<-B, A<-D, change D to depend on nothing, B drops nothing.
241			graph := map[string]*Lineage{}
242			mustRegister(t, graph, "A")
243			mustRegister(t, graph, "B", "A")
244			mustRegister(t, graph, "D", "A")
245			// D used to reach A directly; make D a root while keeping A->? ...
246			// then B cannot depend on D unless safe: D is a root, safe.
247			mustRegister(t, graph, "D")
248			mustRegister(t, graph, "B", "A", "D")
249			if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"A", "D"}) {
250				t.Fatalf("B.Parents = %v, want [A D]", got)
251			}
252		})
253	}
