	b := &Lineage{Dataset: "B", Children: []string{"X", "C", "C"}}
	c := &Lineage{Dataset: "C", Parents: []string{"B"}}
	x := &Lineage{Dataset: "X", Parents: []string{"B"}}
	graph := map[string]*Lineage{"A": a, "B": b, "C": c, "X": x}

