	t.Logf("A.Children = %v", graph["A"].Children)
	if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"X"}) {
		t.Errorf("B.Children = %v, want [X]", got)
	}
	if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"C"}) {
		t.Errorf("A.Children = %v, want [C]", got)
	}
}

