71	//
72	// Registration is atomic. If any parent is missing or the resulting graph
73	// would contain a cycle (including a dataset depending on itself, directly or
74	// through other nodes), no node and no parent/child record is changed. Cycle
75	// validation uses the relationships as they will be AFTER the replacement, so
76	// an edge removed by this registration cannot make a legal change fail.
77	func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
78		if graph == nil {
79			return fmt.Errorf("%w: create the graph map with make before registering datasets", ErrNotInitialized)
80		}
81		if dataset.Name == "" {
82			return fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
83		}
84	
85		// Normalize on a copy: dedupe (duplicates are one relationship), sort,
86		// and detach from the caller's backing array.
87		wanted := uniqueSorted(parents)
88		for _, parent := range wanted {
89			entry, ok := graph[parent]
